-- Additive CRM domain. Existing generic leads/clients are retained until explicit
-- reviewed adoption/linking. Names never auto-merge people or companies.
create table public.billing_crm_sequences(business_id uuid not null references public.billing_businesses(id),demo boolean not null,next_sequence bigint not null default 1 check(next_sequence>0),primary key(business_id,demo));
create table public.billing_crm_capabilities(business_id uuid not null,demo boolean not null,user_id uuid not null references auth.users(id),read_all boolean not null default false,work_all boolean not null default false,manage boolean not null default false,changed_by uuid not null references auth.users(id),primary key(business_id,demo,user_id),foreign key(business_id,demo) references public.billing_crm_sequences(business_id,demo));
create table public.billing_crm_pipelines(id uuid primary key,business_id uuid not null,demo boolean not null,name text not null,version integer not null default 1 check(version>0),archived boolean not null default false,created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),unique(id,business_id,demo),foreign key(business_id,demo) references public.billing_crm_sequences(business_id,demo));
create table public.billing_crm_pipeline_versions(pipeline_id uuid not null,version integer not null,business_id uuid not null,demo boolean not null,name text not null,stages jsonb not null,actor_id uuid not null references auth.users(id),created_at timestamptz not null default now(),primary key(pipeline_id,version),foreign key(pipeline_id,business_id,demo) references public.billing_crm_pipelines(id,business_id,demo));
create table public.billing_crm_stages(pipeline_id uuid not null,pipeline_version integer not null,id uuid not null,business_id uuid not null,demo boolean not null,name text not null,kind text not null check(kind in ('open','won','lost')),position integer not null,probability integer not null check(probability between 0 and 100),primary key(pipeline_id,pipeline_version,id),unique(pipeline_id,pipeline_version,position),foreign key(pipeline_id,pipeline_version) references public.billing_crm_pipeline_versions(pipeline_id,version));
create table public.billing_crm_leads(id uuid primary key,business_id uuid not null,demo boolean not null,pipeline_id uuid not null,pipeline_version integer not null,stage_id uuid not null,owner_id uuid not null references auth.users(id),
 name text not null,company text not null default '',email text not null default '',phone text not null default '',amount numeric(18,2) not null check(amount>=0 and amount<=10000000000),currency text not null,source text not null,notes text not null default '',next_action text not null default '',reason text not null,
 client_id uuid,legacy_record_id uuid unique,legacy_snapshot jsonb,canonical_id uuid,archived boolean not null default false,version integer not null default 1 check(version>0),state_date date not null,created_sequence bigint not null,created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),
 search_vector tsvector generated always as(to_tsvector('simple'::regconfig,name||' '||company||' '||email||' '||phone||' '||source)) stored,
 unique(id,business_id,demo),foreign key(business_id,demo) references public.billing_crm_sequences(business_id,demo),foreign key(pipeline_id,pipeline_version,stage_id) references public.billing_crm_stages(pipeline_id,pipeline_version,id),foreign key(pipeline_id,business_id,demo) references public.billing_crm_pipelines(id,business_id,demo),foreign key(client_id,business_id,demo) references public.billing_records(id,business_id,demo),foreign key(legacy_record_id,business_id,demo) references public.billing_records(id,business_id,demo),foreign key(canonical_id,business_id,demo) references public.billing_crm_leads(id,business_id,demo),check(canonical_id is null or canonical_id<>id));
create index crm_lead_scope on public.billing_crm_leads(business_id,demo,created_sequence,id);
create index crm_lead_owner on public.billing_crm_leads(business_id,demo,owner_id,archived);
create index crm_lead_email on public.billing_crm_leads(business_id,demo,lower(email));
create index crm_lead_phone on public.billing_crm_leads(business_id,demo,(regexp_replace(phone,'[^0-9]','','g')));
create index crm_lead_search on public.billing_crm_leads using gin(search_vector);
create table public.billing_crm_tasks(id uuid primary key,business_id uuid not null,demo boolean not null,lead_id uuid not null,assignee_id uuid not null references auth.users(id),title text not null,due_at timestamptz not null,time_zone text not null,status text not null check(status in ('open','done','cancelled')),version integer not null default 1,state_date date not null,created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(id,business_id,demo),foreign key(lead_id,business_id,demo) references public.billing_crm_leads(id,business_id,demo));
create index crm_task_due on public.billing_crm_tasks(business_id,demo,assignee_id,status,due_at,id);
create table public.billing_crm_activities(id uuid primary key,business_id uuid not null,demo boolean not null,lead_id uuid not null,kind text not null check(kind in ('note','call','meeting','email','whatsapp')),occurred_at timestamptz not null,time_zone text not null,ends_at timestamptz,summary text not null,notes text not null,actor_id uuid not null references auth.users(id),created_at timestamptz not null default now(),foreign key(lead_id,business_id,demo) references public.billing_crm_leads(id,business_id,demo));
create table public.billing_crm_files(id uuid primary key,business_id uuid not null,demo boolean not null,lead_id uuid not null,path text not null unique,name text not null,mime text not null,size integer not null check(size>0 and size<=5242880),sha256 text not null check(sha256~'^[0-9a-f]{64}$'),checksum_provenance text not null default 'recorded-client-fingerprint' check(checksum_provenance='recorded-client-fingerprint'),actor_id uuid not null references auth.users(id),created_at timestamptz not null default now(),foreign key(lead_id,business_id,demo) references public.billing_crm_leads(id,business_id,demo));
create table public.billing_crm_quotes(id uuid primary key,business_id uuid not null,demo boolean not null,lead_id uuid not null,document_id uuid not null unique,lead_version integer not null,snapshot jsonb not null,actor_id uuid not null references auth.users(id),created_at timestamptz not null default now(),foreign key(lead_id,business_id,demo) references public.billing_crm_leads(id,business_id,demo),foreign key(document_id,business_id,demo) references public.billing_records(id,business_id,demo));
create table public.billing_crm_commands(business_id uuid not null,demo boolean not null,command_id uuid not null,actor_id uuid not null references auth.users(id),request jsonb not null,result jsonb not null,created_at timestamptz not null default now(),primary key(business_id,demo,command_id),foreign key(business_id,demo) references public.billing_crm_sequences(business_id,demo));
create table public.billing_crm_events(id uuid primary key default gen_random_uuid(),business_id uuid not null,demo boolean not null,command_id uuid not null,sequence bigint not null,lead_id uuid,kind text not null,effective_date date not null,lead_snapshot jsonb,search_vector tsvector generated always as(to_tsvector('simple'::regconfig,coalesce(lead_snapshot->>'name','')||' '||coalesce(lead_snapshot->>'company','')||' '||coalesce(lead_snapshot->>'email','')||' '||coalesce(lead_snapshot->>'phone','')||' '||coalesce(lead_snapshot->>'source',''))) stored,details jsonb not null,actor_id uuid not null references auth.users(id),created_at timestamptz not null default now(),unique(business_id,demo,sequence),foreign key(lead_id,business_id,demo) references public.billing_crm_leads(id,business_id,demo),foreign key(business_id,demo,command_id) references public.billing_crm_commands(business_id,demo,command_id) deferrable initially deferred);
create index crm_event_search on public.billing_crm_events using gin(search_vector) where lead_snapshot is not null;
create index crm_event_lead on public.billing_crm_events(business_id,demo,lead_id,sequence);
create index crm_event_date on public.billing_crm_events(business_id,demo,effective_date,sequence);
create table public.billing_crm_outbox(id uuid primary key default gen_random_uuid(),business_id uuid not null,demo boolean not null,command_id uuid not null,topic text not null,payload jsonb not null,created_at timestamptz not null default now(),unique(business_id,demo,command_id),foreign key(business_id,demo,command_id) references public.billing_crm_commands(business_id,demo,command_id));

create function public.billing_crm_writer(business uuid,user_id uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.billing_businesses b where b.id=business and b.owner_id=user_id) or exists(select 1 from public.billing_members m where m.business_id=business and m.user_id=billing_crm_writer.user_id and m.role in ('owner','admin','editor'))$$;
create function public.billing_crm_manage(business uuid,data_mode boolean) returns boolean language sql stable security definer set search_path='' as $$select auth.uid() is not null and public.billing_can_access(business,true) and (public.billing_is_owner(business) or exists(select 1 from public.billing_members m where m.business_id=business and m.user_id=auth.uid() and m.role='admin') or exists(select 1 from public.billing_crm_capabilities c where c.business_id=business and c.demo=data_mode and c.user_id=auth.uid() and c.manage))$$;
create function public.billing_crm_canonical(lead uuid) returns uuid language sql stable security definer set search_path='' as $$with recursive chain as(select id,canonical_id,0 depth from public.billing_crm_leads where id=lead union all select l.id,l.canonical_id,c.depth+1 from chain c join public.billing_crm_leads l on l.id=c.canonical_id where c.depth<32)select id from chain where canonical_id is null order by depth desc limit 1$$;
create function public.billing_crm_read_lead(lead uuid) returns boolean language plpgsql stable security definer set search_path='' as $$declare l public.billing_crm_leads;root public.billing_crm_leads;begin select * into l from public.billing_crm_leads where id=lead;if l.id is null or auth.uid() is null or not public.billing_can_access(l.business_id) then return false;end if;select * into root from public.billing_crm_leads where id=public.billing_crm_canonical(lead);return public.billing_crm_manage(l.business_id,l.demo) or exists(select 1 from public.billing_crm_capabilities c where c.business_id=l.business_id and c.demo=l.demo and c.user_id=auth.uid() and (c.read_all or c.work_all and public.billing_can_access(l.business_id,true))) or auth.uid() in (l.owner_id,l.created_by,root.owner_id) or exists(select 1 from public.billing_crm_tasks t where t.lead_id=lead and t.assignee_id=auth.uid());end$$;
create function public.billing_crm_work_lead(lead uuid) returns boolean language plpgsql stable security definer set search_path='' as $$declare l public.billing_crm_leads;begin select * into l from public.billing_crm_leads where id=lead;return l.id is not null and public.billing_can_access(l.business_id,true) and (public.billing_crm_manage(l.business_id,l.demo) or l.owner_id=auth.uid() or exists(select 1 from public.billing_crm_capabilities c where c.business_id=l.business_id and c.demo=l.demo and c.user_id=auth.uid() and c.work_all));end$$;
create function public.billing_crm_next(business uuid,data_mode boolean) returns bigint language plpgsql security definer set search_path='' as $$declare n bigint;begin insert into public.billing_crm_sequences(business_id,demo) values(business,data_mode) on conflict do nothing;update public.billing_crm_sequences set next_sequence=next_sequence+1 where business_id=business and demo=data_mode returning next_sequence-1 into n;return n;end$$;
create function public.billing_crm_emit(business uuid,data_mode boolean,command uuid,n bigint,kind text,lead uuid,day date,snapshot jsonb,details jsonb) returns jsonb language plpgsql security definer set search_path='' as $$declare result jsonb;begin insert into public.billing_crm_events(business_id,demo,command_id,sequence,kind,lead_id,effective_date,lead_snapshot,details,actor_id) values(business,data_mode,command,n,kind,lead,day,snapshot,details,auth.uid()) returning (to_jsonb(billing_crm_events)-'search_vector')||jsonb_build_object('sequence',sequence::text) into result;return result;end$$;
create function public.billing_crm_lead_json(lead uuid) returns jsonb language sql stable security definer set search_path='' as $$select to_jsonb(l)-'search_vector'||jsonb_build_object('amount',l.amount::text,'created_sequence',l.created_sequence::text,'stageName',s.name,'stageKind',s.kind,'pipelineName',p.name) from public.billing_crm_leads l join public.billing_crm_stages s on s.pipeline_id=l.pipeline_id and s.pipeline_version=l.pipeline_version and s.id=l.stage_id join public.billing_crm_pipeline_versions p on p.pipeline_id=l.pipeline_id and p.version=l.pipeline_version where l.id=lead$$;
create function public.billing_crm_immutable() returns trigger language plpgsql set search_path='' as $$begin raise exception 'CRM history is immutable; record a new reviewed action';end$$;
create function public.billing_crm_version_guard() returns trigger language plpgsql set search_path='' as $$begin if tg_op='DELETE' then raise exception 'CRM records are retained; archive or correct through commands';end if;if new.id<>old.id or new.business_id<>old.business_id or new.demo<>old.demo or new.created_by<>old.created_by or new.created_at<>old.created_at or new.version<>old.version+1 then raise exception 'CRM identity/version can only advance through commands';end if;return new;end$$;
create trigger crm_pipeline_version before update or delete on public.billing_crm_pipelines for each row execute function public.billing_crm_version_guard();
create trigger crm_lead_version before update or delete on public.billing_crm_leads for each row execute function public.billing_crm_version_guard();
create trigger crm_task_version before update or delete on public.billing_crm_tasks for each row execute function public.billing_crm_version_guard();
create trigger crm_pipeline_history before update or delete on public.billing_crm_pipeline_versions for each row execute function public.billing_crm_immutable();
create trigger crm_stage_history before update or delete on public.billing_crm_stages for each row execute function public.billing_crm_immutable();
create trigger crm_activity_history before update or delete on public.billing_crm_activities for each row execute function public.billing_crm_immutable();
create trigger crm_file_history before update or delete on public.billing_crm_files for each row execute function public.billing_crm_immutable();
create trigger crm_quote_history before update or delete on public.billing_crm_quotes for each row execute function public.billing_crm_immutable();
create trigger crm_command_history before update or delete on public.billing_crm_commands for each row execute function public.billing_crm_immutable();
create trigger crm_event_history before update or delete on public.billing_crm_events for each row execute function public.billing_crm_immutable();
create trigger crm_outbox_history before update or delete on public.billing_crm_outbox for each row execute function public.billing_crm_immutable();

create function public.billing_crm_command(business uuid,data_mode boolean,command_id uuid,action text,command_data jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare prior public.billing_crm_commands;pipeline public.billing_crm_pipelines;lead public.billing_crm_leads;other public.billing_crm_leads;task public.billing_crm_tasks;legacy public.billing_records;client public.billing_records;stage public.billing_crm_stages;
 request jsonb;result jsonb;details jsonb;event jsonb;doc public.billing_records;item jsonb;stages jsonb='[]';ids uuid[];n bigint;day date;today date;zone text;key_name text;reason text;owner_user uuid;target uuid;lead_id uuid;pipeline_id uuid;stage_id uuid;expected integer;lead_amount numeric(18,2);candidate_ids jsonb;reviewed jsonb;due timestamptz;ends timestamptz;path text;kind text;source_snapshot jsonb;subaction text;
begin
 if auth.uid() is null or not public.billing_can_access(business,true) then raise exception using errcode='42501',message='Your role cannot change CRM in this business';end if;
 if data_mode is null or command_id is null or action is null or action not in ('pipeline.save','pipeline.archive','capabilities','lead.save','lead.adopt','lead.archive','lead.merge','task.save','task.status','activity.add','file.attach','quote.create','client.link') or jsonb_typeof(command_data) is distinct from 'object' then raise exception 'Choose a valid versioned CRM command';end if;
 request=jsonb_build_object('action',action,'data',command_data);
 select * into prior from public.billing_crm_commands c where c.business_id=business and c.demo=data_mode and c.command_id=billing_crm_command.command_id;
 if prior.command_id is not null then if prior.actor_id<>auth.uid() or prior.request<>request then raise exception using errcode='40001',message='Retry key was used for a different CRM command';end if;return prior.result||jsonb_build_object('replayed',true);end if;
 if action='lead.adopt' then
  if coalesce(command_data->>'legacyRecordId','')!~'^[0-9a-fA-F-]{36}$' then raise exception 'Choose an exact legacy lead for adoption';end if;
  -- Existing legacy quote generation holds source-record -> business numbering.
  -- Adoption preserves that order and freezes the version before any CRM write.
  perform 1 from public.billing_records r where r.id=(command_data->>'legacyRecordId')::uuid and r.business_id=business and r.demo=data_mode and r.collection='leads' for update;
 end if;
 perform 1 from public.billing_businesses where id=business for no key update;
 if not public.billing_can_access(business,true) then raise exception using errcode='42501',message='Your CRM permission changed while waiting; reload before writing';end if;
 select * into prior from public.billing_crm_commands c where c.business_id=business and c.demo=data_mode and c.command_id=billing_crm_command.command_id;
 if prior.command_id is not null then if prior.actor_id<>auth.uid() or prior.request<>request then raise exception using errcode='40001',message='Retry key was used for a different CRM command';end if;return prior.result||jsonb_build_object('replayed',true);end if;
 select time_zone,(now() at time zone time_zone)::date into zone,today from public.billing_businesses where id=business;
 day=public.billing_payment_date(coalesce(command_data->'date',to_jsonb(today::text)));if day>today then raise exception 'CRM state changes cannot be future-dated; future follow-ups belong in due/meeting times';end if;
 n=public.billing_crm_next(business,data_mode);details=command_data;
 if action in ('pipeline.save','pipeline.archive','capabilities') then
  if not public.billing_crm_manage(business,data_mode) then raise exception using errcode='42501',message='A CRM manager must review pipeline or routing changes';end if;
  if action='capabilities' then
   if not public.billing_is_owner(business) then raise exception using errcode='42501',message='Only the business owner can grant CRM capabilities';end if;
   if command_data-array['userId','readAll','workAll','manage','date']<>'{}'::jsonb or coalesce(command_data->>'userId','')!~'^[0-9a-fA-F-]{36}$' or jsonb_typeof(command_data->'readAll') is distinct from 'boolean' or jsonb_typeof(command_data->'workAll') is distinct from 'boolean' or jsonb_typeof(command_data->'manage') is distinct from 'boolean' then raise exception 'Review explicit CRM capability flags';end if;
   target=(command_data->>'userId')::uuid;if not exists(select 1 from public.billing_members where business_id=business and user_id=target) and not exists(select 1 from public.billing_businesses where id=business and owner_id=target) then raise exception 'CRM capabilities require a current business member';end if;
   if (command_data->'workAll'='true'::jsonb or command_data->'manage'='true'::jsonb) and not public.billing_crm_writer(business,target) then raise exception 'CRM capabilities cannot bypass a read-only business role';end if;
   insert into public.billing_crm_capabilities(business_id,demo,user_id,read_all,work_all,manage,changed_by) values(business,data_mode,target,(command_data->>'readAll')::boolean,(command_data->>'workAll')::boolean,(command_data->>'manage')::boolean,auth.uid()) on conflict(business_id,demo,user_id) do update set read_all=excluded.read_all,work_all=excluded.work_all,manage=excluded.manage,changed_by=auth.uid();
   result=jsonb_build_object('userId',target,'readAll',command_data->'readAll','workAll',command_data->'workAll','manage',command_data->'manage');
  else
   if coalesce(command_data->>'pipelineId','')!~'^[0-9a-fA-F-]{36}$' or coalesce(command_data->>'version','')!~'^[0-9]{1,9}$' then raise exception 'Choose a versioned pipeline';end if;pipeline_id=(command_data->>'pipelineId')::uuid;expected=(command_data->>'version')::integer;
   select * into pipeline from public.billing_crm_pipelines p where p.id=pipeline_id and p.business_id=business and p.demo=data_mode for update;
   if pipeline.id is null and expected<>0 or pipeline.id is not null and pipeline.version<>expected then raise exception using errcode='40001',message='Pipeline changed; reload before editing';end if;
   if action='pipeline.archive' then
    if command_data-array['pipelineId','version','date','reason']<>'{}'::jsonb or pipeline.id is null or not coalesce(length(btrim(command_data->>'reason')) between 1 and 1000,false) then raise exception 'Choose a pipeline and archive reason';end if;
    if exists(select 1 from public.billing_crm_leads where public.billing_crm_leads.pipeline_id=pipeline.id and not archived and canonical_id is null) then raise exception 'Move or explicitly archive every active lead before archiving its pipeline';end if;
    update public.billing_crm_pipelines set archived=true,version=version+1 where id=pipeline.id returning * into pipeline;
    select v.stages into stages from public.billing_crm_pipeline_versions v where v.pipeline_id=pipeline.id and v.version=expected;
    insert into public.billing_crm_pipeline_versions(pipeline_id,version,business_id,demo,name,stages,actor_id) values(pipeline.id,pipeline.version,business,data_mode,pipeline.name,stages,auth.uid());
    for item in select value from jsonb_array_elements(stages) loop insert into public.billing_crm_stages(pipeline_id,pipeline_version,id,business_id,demo,name,kind,position,probability) values(pipeline.id,pipeline.version,(item->>'id')::uuid,business,data_mode,item->>'name',item->>'kind',(item->>'position')::integer,(item->>'probability')::integer);end loop;

   else
    if command_data-array['pipelineId','version','name','stages','date']<>'{}'::jsonb or jsonb_typeof(command_data->'name') is distinct from 'string' or length(btrim(command_data->>'name')) not between 1 and 180 or jsonb_typeof(command_data->'stages') is distinct from 'array' or jsonb_array_length(command_data->'stages') not between 2 and 30 then raise exception 'Review a pipeline name and 2–30 typed stages';end if;
    ids=array[]::uuid[];expected=expected+1;
    for item in select value from jsonb_array_elements(command_data->'stages') loop
     if jsonb_typeof(item) is distinct from 'object' or item-array['id','name','kind','probability']<>'{}'::jsonb or coalesce(item->>'id','')!~'^[0-9a-fA-F-]{36}$' or jsonb_typeof(item->'name') is distinct from 'string' or length(btrim(item->>'name')) not between 1 and 180 or coalesce(item->>'kind','') not in ('open','won','lost') or coalesce(item->>'probability','')!~'^[0-9]{1,3}$' or (item->>'probability')::integer>100 or (item->>'id')::uuid=any(ids) then raise exception 'Each pipeline stage needs a distinct ID, name, type and 0–100 probability';end if;
     if item->>'kind'='won' and (item->>'probability')::integer<>100 or item->>'kind'='lost' and (item->>'probability')::integer<>0 then raise exception 'Won/lost stages use 100/0 probability';end if;
     ids=array_append(ids,(item->>'id')::uuid);stages=stages||jsonb_build_array(item||jsonb_build_object('position',cardinality(ids),'name',btrim(item->>'name')));
    end loop;
    if not exists(select 1 from jsonb_array_elements(stages)s where s->>'kind'='open') or not exists(select 1 from jsonb_array_elements(stages)s where s->>'kind' in ('won','lost')) then raise exception 'A pipeline needs an open stage and a terminal won/lost stage';end if;
    if pipeline.id is not null and exists(select 1 from public.billing_crm_leads l where l.pipeline_id=pipeline.id and not l.archived and l.canonical_id is null and not(l.stage_id=any(ids))) then raise exception 'Move active leads before removing a referenced stage';end if;
    if pipeline.id is null then insert into public.billing_crm_pipelines(id,business_id,demo,name,created_by) values(pipeline_id,business,data_mode,btrim(command_data->>'name'),auth.uid()) returning * into pipeline;
    else update public.billing_crm_pipelines set name=btrim(command_data->>'name'),version=expected,archived=false where id=pipeline.id returning * into pipeline;end if;
    insert into public.billing_crm_pipeline_versions(pipeline_id,version,business_id,demo,name,stages,actor_id) values(pipeline.id,pipeline.version,business,data_mode,pipeline.name,stages,auth.uid());
    for item in select value from jsonb_array_elements(stages) loop insert into public.billing_crm_stages(pipeline_id,pipeline_version,id,business_id,demo,name,kind,position,probability) values(pipeline.id,pipeline.version,(item->>'id')::uuid,business,data_mode,item->>'name',item->>'kind',(item->>'position')::integer,(item->>'probability')::integer);end loop;
   end if;
   result=jsonb_build_object('pipeline',to_jsonb(pipeline),'stages',stages);
  end if;
 elsif action in ('lead.save','lead.adopt') then
  if command_data-array['leadId','version','pipelineId','stageId','ownerId','name','company','email','phone','amount','currency','source','notes','nextAction','reason','clientId','date','duplicatePolicy','reviewedDuplicates','legacyRecordId','legacyVersion']<>'{}'::jsonb or coalesce(command_data->>'leadId','')!~'^[0-9a-fA-F-]{36}$' or coalesce(command_data->>'version','')!~'^[0-9]{1,9}$' or coalesce(command_data->>'pipelineId','')!~'^[0-9a-fA-F-]{36}$' or coalesce(command_data->>'stageId','')!~'^[0-9a-fA-F-]{36}$' or coalesce(command_data->>'ownerId','')!~'^[0-9a-fA-F-]{36}$' then raise exception 'Choose a versioned lead, pipeline, stage and owner';end if;
  lead_id=(command_data->>'leadId')::uuid;owner_user=(command_data->>'ownerId')::uuid;expected=(command_data->>'version')::integer;
  select * into lead from public.billing_crm_leads l where l.id=lead_id and l.business_id=business and l.demo=data_mode for update;
  if lead.id is null and expected<>0 or lead.id is not null and lead.version<>expected then raise exception using errcode='40001',message='Lead changed; reload before saving';end if;
  if lead.id is not null and (not public.billing_crm_work_lead(lead.id) or lead.archived or lead.canonical_id is not null) then raise exception using errcode='42501',message='Choose an active lead you can work';end if;
  if not public.billing_crm_manage(business,data_mode) and (lead.id is null and owner_user<>auth.uid() or lead.id is not null and owner_user<>lead.owner_id) then raise exception using errcode='42501',message='A CRM manager must review ownership reassignment';end if;
  if not public.billing_crm_writer(business,owner_user) then raise exception 'Assign leads to a current business owner/admin/editor';end if;
  if lead.id is not null and day<lead.state_date then raise exception 'State changes cannot predate the latest lead state; backdated interactions use the timeline';end if;
  select * into pipeline from public.billing_crm_pipelines p where p.id=(command_data->>'pipelineId')::uuid and p.business_id=business and p.demo=data_mode and not p.archived;
  select * into stage from public.billing_crm_stages s where s.pipeline_id=pipeline.id and s.pipeline_version=pipeline.version and s.id=(command_data->>'stageId')::uuid;
  if stage.id is null then raise exception 'Choose a current stage in an active pipeline';end if;
  foreach key_name in array array['name','company','email','phone','source','notes','nextAction','reason'] loop
   if jsonb_typeof(command_data->key_name) is distinct from 'string' or length(command_data->>key_name)>(case key_name when 'notes' then 10000 when 'email' then 254 when 'phone' then 80 when 'source' then 180 when 'reason' then 1000 when 'nextAction' then 1000 else 500 end) then raise exception 'Review CRM contact/source/notes text lengths';end if;
  end loop;
  if length(btrim(command_data->>'name'))=0 or length(btrim(command_data->>'source'))=0 or length(btrim(command_data->>'reason'))=0 or (stage.kind='open' and length(btrim(command_data->>'nextAction'))=0) then raise exception 'Retain lead name, source, reason and an open-stage next action';end if;
  if btrim(command_data->>'email')<>'' and btrim(command_data->>'email')!~'^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' or coalesce(command_data->>'currency','')!~'^[A-Z]{3}$' then raise exception 'Review the lead email and separate expected-value currency';end if;
  lead_amount=public.billing_ledger_amount(command_data->'amount');
  select coalesce(jsonb_agg(l.id::text order by l.id),'[]'::jsonb) into candidate_ids from public.billing_crm_leads l where l.business_id=business and l.demo=data_mode and l.id<>lead_id and l.canonical_id is null and not l.archived and ((btrim(command_data->>'email')<>'' and lower(l.email)=lower(btrim(command_data->>'email'))) or (regexp_replace(command_data->>'phone','[^0-9]','','g')<>'' and regexp_replace(l.phone,'[^0-9]','','g')=regexp_replace(command_data->>'phone','[^0-9]','','g')));
  if candidate_ids<>'[]'::jsonb and (lead.id is null or lower(lead.email)<>lower(btrim(command_data->>'email')) or regexp_replace(lead.phone,'[^0-9]','','g')<>regexp_replace(command_data->>'phone','[^0-9]','','g')) then
   if command_data->>'duplicatePolicy' is distinct from 'allow-reviewed' or jsonb_typeof(command_data->'reviewedDuplicates') is distinct from 'array' then raise exception using errcode='23505',message='Matching enquiries require explicit duplicate ownership review; no record was merged';end if;
   select coalesce(jsonb_agg(value order by value),'[]'::jsonb) into reviewed from jsonb_array_elements(command_data->'reviewedDuplicates');
   if reviewed<>candidate_ids or exists(select 1 from jsonb_array_elements_text(candidate_ids)c where not public.billing_crm_read_lead(c::uuid)) then raise exception using errcode='40001',message='Duplicate candidates changed or require a CRM manager review';end if;
  end if;
  if command_data->'clientId' is not null and command_data->'clientId'<>'null'::jsonb then
   if coalesce(command_data->>'clientId','')!~'^[0-9a-fA-F-]{36}$' then raise exception 'Choose an exact saved client link';end if;
   select * into client from public.billing_records r where r.id=(command_data->>'clientId')::uuid and r.business_id=business and r.demo=data_mode and r.collection='clients';
   if client.id is null or client.archived and client.id is distinct from lead.client_id then raise exception 'Client link unavailable in this business and data mode';end if;
  end if;
  if action='lead.adopt' then
   if lead.id is not null or coalesce(command_data->>'legacyRecordId','')!~'^[0-9a-fA-F-]{36}$' or coalesce(command_data->>'legacyVersion','')!~'^[1-9][0-9]{0,8}$' then raise exception 'Explicit adoption needs an unchanged legacy lead';end if;
   select * into legacy from public.billing_records r where r.id=(command_data->>'legacyRecordId')::uuid and r.business_id=business and r.demo=data_mode and r.collection='leads' and not r.archived;
   if legacy.id is null or legacy.version<>(command_data->>'legacyVersion')::integer then raise exception using errcode='40001',message='Legacy lead changed; review adoption again';end if;
  elsif command_data?'legacyRecordId' or command_data?'legacyVersion' then raise exception 'Use explicit legacy adoption; ordinary saves cannot forge provenance';end if;
  if lead.id is null then
   insert into public.billing_crm_leads(id,business_id,demo,pipeline_id,pipeline_version,stage_id,owner_id,name,company,email,phone,amount,currency,source,notes,next_action,reason,client_id,legacy_record_id,legacy_snapshot,state_date,created_sequence,created_by)
   values(lead_id,business,data_mode,pipeline.id,pipeline.version,stage.id,owner_user,btrim(command_data->>'name'),btrim(command_data->>'company'),btrim(command_data->>'email'),btrim(command_data->>'phone'),lead_amount,command_data->>'currency',btrim(command_data->>'source'),command_data->>'notes',command_data->>'nextAction',command_data->>'reason',client.id,legacy.id,case when legacy.id is null then null else to_jsonb(legacy) end,day,n,auth.uid()) returning * into lead;
  else
   update public.billing_crm_leads set pipeline_id=pipeline.id,pipeline_version=pipeline.version,stage_id=stage.id,owner_id=owner_user,name=btrim(command_data->>'name'),company=btrim(command_data->>'company'),email=btrim(command_data->>'email'),phone=btrim(command_data->>'phone'),amount=lead_amount,currency=command_data->>'currency',source=btrim(command_data->>'source'),notes=command_data->>'notes',next_action=command_data->>'nextAction',reason=command_data->>'reason',client_id=client.id,version=version+1,state_date=day,updated_at=now() where id=lead.id returning * into lead;
  end if;
  result=jsonb_build_object('lead',public.billing_crm_lead_json(lead.id));
 else
  if coalesce(command_data->>'leadId','')!~'^[0-9a-fA-F-]{36}$' then raise exception 'Choose an exact CRM lead';end if;lead_id=(command_data->>'leadId')::uuid;
  select * into lead from public.billing_crm_leads l where l.id=lead_id and l.business_id=business and l.demo=data_mode for update;
  if lead.id is null then raise exception using errcode='P0002',message='CRM lead unavailable in this business and data mode';end if;
  if action in ('task.status') then
   if not public.billing_crm_work_lead(coalesce(public.billing_crm_canonical(lead.id),lead.id)) and not exists(select 1 from public.billing_crm_tasks t where t.id=(command_data->>'taskId')::uuid and t.lead_id=lead.id and t.assignee_id=auth.uid()) then raise exception using errcode='42501',message='Only the task assignee or a lead/CRM manager can complete it';end if;
  elsif not public.billing_crm_work_lead(lead.id) or lead.archived or lead.canonical_id is not null then raise exception using errcode='42501',message='Choose an active lead you can work';end if;
  if action<>'task.status' and (coalesce(command_data->>'version','')!~'^[1-9][0-9]{0,8}$' or lead.version<>(command_data->>'version')::integer) then raise exception using errcode='40001',message='Lead changed; reload before acting';end if;
  if action='lead.archive' then
   if command_data-array['leadId','version','date','reason']<>'{}'::jsonb or not coalesce(length(btrim(command_data->>'reason')) between 1 and 1000,false) or day<lead.state_date then raise exception 'Archive needs a current effective date and reason';end if;
   update public.billing_crm_leads set archived=true,reason=command_data->>'reason',state_date=day,version=version+1,updated_at=now() where id=lead.id returning * into lead;result=jsonb_build_object('lead',public.billing_crm_lead_json(lead.id));
  elsif action='lead.merge' then
   if not public.billing_crm_manage(business,data_mode) then raise exception using errcode='42501',message='A CRM manager must review duplicate merge and surviving ownership';end if;
   if command_data-array['leadId','version','targetId','targetVersion','ownerId','date','reason','reviewed']<>'{}'::jsonb or command_data->'reviewed' is distinct from 'true'::jsonb or coalesce(command_data->>'targetId','')!~'^[0-9a-fA-F-]{36}$' or coalesce(command_data->>'targetVersion','')!~'^[1-9][0-9]{0,8}$' or coalesce(command_data->>'ownerId','')!~'^[0-9a-fA-F-]{36}$' or not coalesce(length(btrim(command_data->>'reason')) between 1 and 1000,false) then raise exception 'Review exact duplicate versions, survivor owner and reason';end if;
   target=(command_data->>'targetId')::uuid;owner_user=(command_data->>'ownerId')::uuid;select * into other from public.billing_crm_leads l where l.id=target and l.business_id=business and l.demo=data_mode for update;
   if other.id is null or other.id=lead.id or other.archived or other.canonical_id is not null or other.version<>(command_data->>'targetVersion')::integer or day<greatest(lead.state_date,other.state_date) then raise exception using errcode='40001',message='Merge sources changed or survivor is unavailable';end if;
   if not public.billing_crm_writer(business,owner_user) then raise exception 'Review an active survivor owner';end if;
   update public.billing_crm_leads set canonical_id=other.id,archived=true,reason=command_data->>'reason',state_date=day,version=version+1,updated_at=now() where id=lead.id returning * into lead;
   perform public.billing_crm_emit(business,data_mode,command_id,n,'lead.merged-source',lead.id,day,public.billing_crm_lead_json(lead.id),command_data);
   n=public.billing_crm_next(business,data_mode);update public.billing_crm_leads set owner_id=owner_user,reason=command_data->>'reason',state_date=day,version=version+1,updated_at=now() where id=other.id returning * into other;
   result=jsonb_build_object('source',public.billing_crm_lead_json(lead.id),'lead',public.billing_crm_lead_json(other.id),'historyRetainedOnSourceIds',true);lead=other;
  elsif action='task.save' then
   if command_data-array['leadId','version','taskId','taskVersion','assigneeId','title','dueAt','timeZone','date']<>'{}'::jsonb or coalesce(command_data->>'taskId','')!~'^[0-9a-fA-F-]{36}$' or coalesce(command_data->>'taskVersion','')!~'^[0-9]{1,9}$' or coalesce(command_data->>'assigneeId','')!~'^[0-9a-fA-F-]{36}$' or jsonb_typeof(command_data->'title') is distinct from 'string' or length(btrim(command_data->>'title')) not between 1 and 500 or coalesce(command_data->>'dueAt','')!~'(Z|[+-][0-9]{2}:[0-9]{2})$' or not exists(select 1 from pg_catalog.pg_timezone_names where name=command_data->>'timeZone') then raise exception 'Review an assigned follow-up with an explicit time zone/UTC offset';end if;
   owner_user=(command_data->>'assigneeId')::uuid;if not public.billing_crm_writer(business,owner_user) then raise exception 'Assign follow-ups to a current business writer';end if;due=(command_data->>'dueAt')::timestamptz;if not isfinite(due) then raise exception 'Choose a real follow-up time';end if;
   select * into task from public.billing_crm_tasks t where t.id=(command_data->>'taskId')::uuid and t.business_id=business and t.demo=data_mode and t.lead_id=lead.id for update;
   if task.id is null then if (command_data->>'taskVersion')::integer<>0 then raise exception using errcode='40001',message='Task unavailable; reload';end if;insert into public.billing_crm_tasks(id,business_id,demo,lead_id,assignee_id,title,due_at,time_zone,status,state_date,created_by) values((command_data->>'taskId')::uuid,business,data_mode,lead.id,owner_user,btrim(command_data->>'title'),due,command_data->>'timeZone','open',day,auth.uid()) returning * into task;
   else if task.version<>(command_data->>'taskVersion')::integer or day<task.state_date then raise exception using errcode='40001',message='Task changed; reload';end if;update public.billing_crm_tasks set assignee_id=owner_user,title=btrim(command_data->>'title'),due_at=due,time_zone=command_data->>'timeZone',state_date=day,status='open',version=version+1,updated_at=now() where id=task.id returning * into task;end if;
   details=details||jsonb_build_object('task',to_jsonb(task));result=jsonb_build_object('task',to_jsonb(task),'lead',public.billing_crm_lead_json(lead.id));
  elsif action='task.status' then
   if command_data-array['leadId','taskId','taskVersion','status','date','reason']<>'{}'::jsonb or coalesce(command_data->>'taskId','')!~'^[0-9a-fA-F-]{36}$' or coalesce(command_data->>'taskVersion','')!~'^[1-9][0-9]{0,8}$' or coalesce(command_data->>'status','') not in ('done','cancelled') or not coalesce(length(btrim(command_data->>'reason')) between 1 and 1000,false) then raise exception 'Review task completion/cancellation and reason';end if;
   select * into task from public.billing_crm_tasks t where t.id=(command_data->>'taskId')::uuid and t.business_id=business and t.demo=data_mode and t.lead_id=lead.id for update;
   if task.id is null or task.version<>(command_data->>'taskVersion')::integer or day<task.state_date then raise exception using errcode='40001',message='Task changed; reload';end if;
   update public.billing_crm_tasks set status=command_data->>'status',state_date=day,version=version+1,updated_at=now() where id=task.id returning * into task;details=details||jsonb_build_object('task',to_jsonb(task));result=jsonb_build_object('task',to_jsonb(task));
  elsif action='activity.add' then
   if command_data-array['leadId','version','kind','occurredAt','endsAt','timeZone','summary','notes','date']<>'{}'::jsonb or coalesce(command_data->>'kind','') not in ('note','call','meeting','email','whatsapp') or coalesce(command_data->>'occurredAt','')!~'(Z|[+-][0-9]{2}:[0-9]{2})$' or not exists(select 1 from pg_catalog.pg_timezone_names where name=command_data->>'timeZone') or jsonb_typeof(command_data->'summary') is distinct from 'string' or length(btrim(command_data->>'summary')) not between 1 and 500 or jsonb_typeof(command_data->'notes') is distinct from 'string' or length(command_data->>'notes')>10000 then raise exception 'Review a dated interaction, time zone and summary';end if;
   due=(command_data->>'occurredAt')::timestamptz;if not isfinite(due) or command_data->>'kind'<>'meeting' and due>now() then raise exception 'Future interactions must be scheduled meetings or follow-ups';end if;
   if command_data->'endsAt' is not null and command_data->'endsAt'<>'null'::jsonb then ends=(command_data->>'endsAt')::timestamptz;if ends<=due or not isfinite(ends) then raise exception 'Meeting end must follow its start';end if;end if;
   insert into public.billing_crm_activities(id,business_id,demo,lead_id,kind,occurred_at,time_zone,ends_at,summary,notes,actor_id) values(gen_random_uuid(),business,data_mode,lead.id,command_data->>'kind',due,command_data->>'timeZone',ends,btrim(command_data->>'summary'),command_data->>'notes',auth.uid()) returning to_jsonb(billing_crm_activities) into result;
   details=details||jsonb_build_object('activity',result,'delivery','logged-only-no-provider-send');result=jsonb_build_object('activity',result);
  elsif action='client.link' then
   if command_data-array['leadId','version','clientId','create','name','address','date','reason']<>'{}'::jsonb or not coalesce(length(btrim(command_data->>'reason')) between 1 and 1000,false) or day<lead.state_date then raise exception 'Review an exact client link or explicit new client creation and reason';end if;
   if command_data->'create'='true'::jsonb then
    if jsonb_typeof(command_data->'name') is distinct from 'string' or length(btrim(command_data->>'name')) not between 1 and 500 or jsonb_typeof(command_data->'address') is distinct from 'string' or length(command_data->>'address')>2000 then raise exception 'Review the new client name and address';end if;
    if exists(select 1 from public.billing_records r where r.business_id=business and r.demo=data_mode and r.collection='clients' and not r.archived and (lead.email<>'' and lower(r.data->>'email')=lower(lead.email) or regexp_replace(lead.phone,'[^0-9]','','g')<>'' and regexp_replace(r.data->>'phone','[^0-9]','','g')=regexp_replace(lead.phone,'[^0-9]','','g'))) then raise exception using errcode='23505',message='A saved client has this exact email/phone. Review and link its ID; no client was merged';end if;
    insert into public.billing_records(business_id,collection,data,demo,created_by) values(business,'clients',jsonb_build_object('name',btrim(command_data->>'name'),'address',command_data->>'address','email',lead.email,'phone',lead.phone,'crmLeadId',lead.id,'sourceRecord',lead.id),data_mode,auth.uid()) returning * into client;
   else
    if coalesce(command_data->>'clientId','')!~'^[0-9a-fA-F-]{36}$' then raise exception 'Choose an exact saved client';end if;
    select * into client from public.billing_records r where r.id=(command_data->>'clientId')::uuid and r.business_id=business and r.demo=data_mode and r.collection='clients' and not r.archived;
    if client.id is null then raise exception 'Client unavailable in this business/data mode';end if;
   end if;
   update public.billing_crm_leads set client_id=client.id,reason=command_data->>'reason',state_date=day,version=version+1,updated_at=now() where id=lead.id returning * into lead;details=details||jsonb_build_object('clientId',client.id,'created',command_data->'create'='true'::jsonb);result=jsonb_build_object('lead',public.billing_crm_lead_json(lead.id),'client',to_jsonb(client));
  elsif action='file.attach' then
   if command_data-array['leadId','version','path','name','mime','size','sha256','date']<>'{}'::jsonb or jsonb_typeof(command_data->'path') is distinct from 'string' or jsonb_typeof(command_data->'name') is distinct from 'string' or length(command_data->>'name') not between 1 and 180 or coalesce(command_data->>'mime','') not in ('application/pdf','image/png','image/jpeg','image/webp','text/csv') or coalesce(command_data->>'size','')!~'^[0-9]{1,7}$' or (command_data->>'size')::integer not between 1 and 5242880 or coalesce(command_data->>'sha256','')!~'^[0-9a-f]{64}$' then raise exception 'Review a PDF/image/CSV attachment up to 5 MB and its checksum';end if;
   path=command_data->>'path';if path not like business::text||'/crm/'||lead.id::text||'/%' or path~'\.\.' or (length(path)>300 or path!~'^[a-zA-Z0-9/._-]+$') or not exists(select 1 from storage.objects o where o.bucket_id='billing-files' and o.name=path) then raise exception 'Upload the private file under this CRM lead first';end if;
   insert into public.billing_crm_files(id,business_id,demo,lead_id,path,name,mime,size,sha256,actor_id) values(gen_random_uuid(),business,data_mode,lead.id,path,command_data->>'name',command_data->>'mime',(command_data->>'size')::integer,command_data->>'sha256',auth.uid()) returning to_jsonb(billing_crm_files) into result;details=details||jsonb_build_object('file',result);result=jsonb_build_object('file',result);
  else
   if command_data-array['leadId','version','date','description','notes']<>'{}'::jsonb or jsonb_typeof(command_data->'description') is distinct from 'string' or length(btrim(command_data->>'description')) not between 1 and 500 or jsonb_typeof(command_data->'notes') is distinct from 'string' or length(command_data->>'notes')>5000 then raise exception 'Review a draft quotation description and notes';end if;
   if lead.client_id is not null then select * into client from public.billing_records where id=lead.client_id and business_id=business and demo=data_mode and collection='clients';end if;
   source_snapshot=public.billing_crm_lead_json(lead.id);
   insert into public.billing_records(business_id,collection,data,demo,created_by) values(business,'documents',jsonb_build_object('type','quotation','number',public.billing_next_document_number(business),'status','draft','date',day,'dueDate','','currency',lead.currency,'seller',(select jsonb_build_object('name',b.name,'address',b.address,'email',b.email,'phone',b.phone,'gstin',b.gstin) from public.billing_businesses b where b.id=business),'buyer',case when client.id is null then jsonb_build_object('name',lead.name,'email',lead.email,'phone',lead.phone) else client.data end,'clientId',client.id,'taxType','NONE','gstMode','split','items',jsonb_build_array(jsonb_build_object('name',btrim(command_data->>'description'),'quantity',1,'rate',lead.amount,'taxRate',0)),'notes',command_data->>'notes','sourceRecord',lead.id,'crmLeadId',lead.id,'crmCanonicalLeadId',public.billing_crm_canonical(lead.id),'crmLeadVersion',lead.version,'crmPipelineId',lead.pipeline_id),data_mode,auth.uid()) returning * into doc;
   insert into public.billing_crm_quotes(id,business_id,demo,lead_id,document_id,lead_version,snapshot,actor_id) values(gen_random_uuid(),business,data_mode,lead.id,doc.id,lead.version,source_snapshot,auth.uid());details=details||jsonb_build_object('documentId',doc.id,'documentNumber',doc.data->>'number','draftOnly',true);result=jsonb_build_object('document',to_jsonb(doc),'lead',source_snapshot);
  end if;
 end if;
 event=public.billing_crm_emit(business,data_mode,command_id,n,action,lead.id,day,case when lead.id is null or action not in ('lead.save','lead.adopt','lead.archive','lead.merge','client.link') then null else public.billing_crm_lead_json(lead.id) end,details);
 result=result||jsonb_build_object('event',event,'replayed',false);
 insert into public.billing_crm_commands(business_id,demo,command_id,actor_id,request,result) values(business,data_mode,command_id,auth.uid(),request,result);
 insert into public.billing_crm_outbox(business_id,demo,command_id,topic,payload) values(business,data_mode,command_id,'crm.'||action,jsonb_build_object('eventId',event->>'id','sequence',event->>'sequence','leadId',lead.id,'providerSend',false));return result;
end$$;

create function public.billing_crm_legacy_guard() returns trigger language plpgsql security definer set search_path='' as $$begin if old.collection='leads' and exists(select 1 from public.billing_crm_leads where legacy_record_id=old.id) then raise exception 'This legacy lead was explicitly adopted into CRM; use its CRM command and retain the original source';end if;if tg_op='DELETE' then return old;end if;return new;end$$;
create trigger billing_95_crm_legacy before update or delete on public.billing_records for each row execute function public.billing_crm_legacy_guard();
create function public.billing_crm_quote_guard() returns trigger language plpgsql security definer set search_path='' as $$declare link public.billing_crm_quotes;begin
 if new.collection<>'documents' then return new;end if;select * into link from public.billing_crm_quotes where document_id=new.id;
 if link.id is not null and (new.data->>'crmLeadId' is distinct from link.lead_id::text or new.data->>'sourceRecord' is distinct from link.lead_id::text or new.data->>'crmCanonicalLeadId' is distinct from link.lead_id::text or new.data->>'crmLeadVersion' is distinct from link.lead_version::text or new.data->>'crmPipelineId' is distinct from link.snapshot->>'pipeline_id') then raise exception 'CRM quotation provenance is immutable; retain its canonical source fields';end if;return new;
end$$;
create trigger billing_96_crm_quote before update on public.billing_records for each row execute function public.billing_crm_quote_guard();
create function public.billing_crm_storage_allowed(path text,write_access boolean default false) returns boolean language plpgsql stable security definer set search_path='' as $$declare lead uuid;l public.billing_crm_leads;begin if split_part(path,'/',2)<>'crm' then return true;end if;if split_part(path,'/',1)!~'^[0-9a-fA-F-]{36}$' or split_part(path,'/',3)!~'^[0-9a-fA-F-]{36}$' then return false;end if;lead=split_part(path,'/',3)::uuid;select * into l from public.billing_crm_leads where id=lead;return l.id is not null and l.business_id=split_part(path,'/',1)::uuid and case when write_access then public.billing_crm_work_lead(lead) and l.canonical_id is null and not l.archived else public.billing_crm_read_lead(lead) end;end$$;
create policy crm_file_read_restrict on storage.objects as restrictive for select to authenticated using(bucket_id<>'billing-files' or public.billing_crm_storage_allowed(name,false));
create policy crm_file_insert_restrict on storage.objects as restrictive for insert to authenticated with check(bucket_id<>'billing-files' or public.billing_crm_storage_allowed(name,true));
create policy crm_file_delete_restrict on storage.objects as restrictive for delete to authenticated using(bucket_id<>'billing-files' or split_part(name,'/',2)<>'crm' or public.billing_crm_storage_allowed(name,true) and not exists(select 1 from public.billing_crm_files f where f.path=storage.objects.name));
create policy crm_file_update_restrict on storage.objects as restrictive for update to authenticated using(bucket_id<>'billing-files' or split_part(name,'/',2)<>'crm' or public.billing_crm_storage_allowed(name,true) and not exists(select 1 from public.billing_crm_files f where f.path=storage.objects.name)) with check(bucket_id<>'billing-files' or split_part(name,'/',2)<>'crm' or public.billing_crm_storage_allowed(name,true) and not exists(select 1 from public.billing_crm_files f where f.path=storage.objects.name));

alter table public.billing_crm_sequences enable row level security;alter table public.billing_crm_capabilities enable row level security;alter table public.billing_crm_pipelines enable row level security;alter table public.billing_crm_pipeline_versions enable row level security;alter table public.billing_crm_stages enable row level security;alter table public.billing_crm_leads enable row level security;alter table public.billing_crm_tasks enable row level security;alter table public.billing_crm_activities enable row level security;alter table public.billing_crm_files enable row level security;alter table public.billing_crm_quotes enable row level security;alter table public.billing_crm_commands enable row level security;alter table public.billing_crm_events enable row level security;alter table public.billing_crm_outbox enable row level security;
revoke all on public.billing_crm_sequences,public.billing_crm_capabilities,public.billing_crm_pipelines,public.billing_crm_pipeline_versions,public.billing_crm_stages,public.billing_crm_leads,public.billing_crm_tasks,public.billing_crm_activities,public.billing_crm_files,public.billing_crm_quotes,public.billing_crm_commands,public.billing_crm_events,public.billing_crm_outbox from public,anon,authenticated;
grant select on public.billing_crm_capabilities,public.billing_crm_pipelines,public.billing_crm_pipeline_versions,public.billing_crm_stages,public.billing_crm_leads,public.billing_crm_tasks,public.billing_crm_activities,public.billing_crm_files,public.billing_crm_quotes,public.billing_crm_events to authenticated;
create policy crm_cap_read on public.billing_crm_capabilities for select to authenticated using(public.billing_can_access(business_id) and(user_id=auth.uid() or public.billing_crm_manage(business_id,demo)));
create policy crm_pipeline_read on public.billing_crm_pipelines for select to authenticated using(public.billing_can_access(business_id));
create policy crm_pipeline_version_read on public.billing_crm_pipeline_versions for select to authenticated using(public.billing_can_access(business_id));
create policy crm_stage_read on public.billing_crm_stages for select to authenticated using(public.billing_can_access(business_id));
create policy crm_lead_read on public.billing_crm_leads for select to authenticated using(public.billing_crm_read_lead(id));
create policy crm_task_read on public.billing_crm_tasks for select to authenticated using(public.billing_crm_read_lead(lead_id));
create policy crm_activity_read on public.billing_crm_activities for select to authenticated using(public.billing_crm_read_lead(lead_id));
create policy crm_file_read on public.billing_crm_files for select to authenticated using(public.billing_crm_read_lead(lead_id));
create policy crm_quote_read on public.billing_crm_quotes for select to authenticated using(public.billing_crm_read_lead(lead_id));
create policy crm_event_read on public.billing_crm_events for select to authenticated using(case when lead_id is not null then public.billing_crm_read_lead(lead_id) else public.billing_can_access(business_id) and(kind like 'pipeline.%' or public.billing_crm_manage(business_id,demo)) end);

create function public.billing_crm_read(business uuid,data_mode boolean,as_of date,lead_id uuid default null,after_sequence bigint default null,page_size integer default 50,snapshot_number bigint default null,search text default '',pipeline_id uuid default null,owner_id uuid default null,include_archived boolean default false) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare ceiling bigint;current_ceiling bigint;pipelines jsonb;people jsonb;rows jsonb;detail jsonb=null;timeline jsonb='[]';activities jsonb='[]';tasks jsonb='[]';files jsonb='[]';quotes jsonb='[]';aliases jsonb='[]';grouped jsonb;conversions jsonb;task_summary jsonb;cursor_valid boolean;next_cursor jsonb=null;lead_count bigint;legacy_count bigint;event_count bigint=0;detail_can_work boolean=false;current_version integer;root_id uuid;parent_id uuid;depth integer=0;family uuid[];today date;business_name text;zone text;
begin
 if auth.uid() is null or not public.billing_can_access(business) then raise exception using errcode='42501',message='CRM unavailable in this business';end if;
 if data_mode is null or as_of is null or not isfinite(as_of) or page_size is null or page_size not between 1 and 100 or search is null or length(search)>200 or include_archived is null then raise exception 'Choose a CRM date, search and page size';end if;
 select name,time_zone,(now() at time zone time_zone)::date into business_name,zone,today from public.billing_businesses where id=business;
 select coalesce(next_sequence-1,0) into current_ceiling from public.billing_crm_sequences where business_id=business and demo=data_mode;current_ceiling=coalesce(current_ceiling,0);ceiling=coalesce(snapshot_number,current_ceiling);
 if ceiling<0 or ceiling>current_ceiling or after_sequence is not null and (snapshot_number is null or after_sequence<1 or after_sequence>ceiling) then raise exception 'Use a valid complete CRM snapshot cursor';end if;
 select coalesce(jsonb_agg(to_jsonb(p)||jsonb_build_object('stages',coalesce((select jsonb_agg(jsonb_build_object('id',s.id,'name',s.name,'kind',s.kind,'position',s.position,'probability',s.probability) order by s.position) from public.billing_crm_stages s where s.pipeline_id=p.id and s.pipeline_version=p.version),'[]'::jsonb)) order by p.name,p.id),'[]'::jsonb) into pipelines from public.billing_crm_pipelines p where p.business_id=business and p.demo=data_mode;
 with members as(select b.owner_id user_id,'owner'::text role from public.billing_businesses b where b.id=business union select user_id,role from public.billing_members where business_id=business)
 select coalesce(jsonb_agg(jsonb_build_object('id',m.user_id,'role',m.role,'email',to_jsonb(u)->>'email','canOwn',public.billing_crm_writer(business,m.user_id)) order by m.role,m.user_id),'[]'::jsonb) into people from members m join auth.users u on u.id=m.user_id;
 with states as(select distinct on(e.lead_id)e.lead_id,e.lead_snapshot,e.sequence,e.search_vector from public.billing_crm_events e where e.business_id=business and e.demo=data_mode and e.lead_snapshot is not null and e.effective_date<=as_of and e.sequence<=ceiling and public.billing_crm_read_lead(e.lead_id) order by e.lead_id,e.effective_date desc,e.sequence desc),visible as(select * from states s where (include_archived or s.lead_snapshot->'archived'='false'::jsonb) and (pipeline_id is null or s.lead_snapshot->>'pipeline_id'=billing_crm_read.pipeline_id::text) and (owner_id is null or s.lead_snapshot->>'owner_id'=billing_crm_read.owner_id::text) and (btrim(search)='' or s.search_vector@@websearch_to_tsquery('simple',search)))
 select count(*),coalesce(bool_or((lead_snapshot->>'created_sequence')::bigint=after_sequence),false) into lead_count,cursor_valid from visible;
 if lead_id is null and after_sequence is not null and not cursor_valid then raise exception 'CRM cursor does not belong to this dated filtered scope';end if;
 with states as(select distinct on(e.lead_id)e.lead_id,e.lead_snapshot,e.sequence,e.search_vector from public.billing_crm_events e where e.business_id=business and e.demo=data_mode and e.lead_snapshot is not null and e.effective_date<=as_of and e.sequence<=ceiling and public.billing_crm_read_lead(e.lead_id) order by e.lead_id,e.effective_date desc,e.sequence desc),visible as(select * from states s where (include_archived or s.lead_snapshot->'archived'='false'::jsonb) and (pipeline_id is null or s.lead_snapshot->>'pipeline_id'=billing_crm_read.pipeline_id::text) and (owner_id is null or s.lead_snapshot->>'owner_id'=billing_crm_read.owner_id::text) and (btrim(search)='' or s.search_vector@@websearch_to_tsquery('simple',search))),page as(select * from visible where after_sequence is null or (lead_snapshot->>'created_sequence')::bigint>after_sequence order by (lead_snapshot->>'created_sequence')::bigint limit page_size+1)
 select coalesce(jsonb_agg(lead_snapshot||jsonb_build_object('snapshotSequence',sequence::text) order by (lead_snapshot->>'created_sequence')::bigint),'[]'::jsonb) into rows from page;
 if jsonb_array_length(rows)>page_size then if lead_id is null then next_cursor=jsonb_build_object('after',(rows->(page_size-1)->>'created_sequence'),'snapshot',ceiling::text);end if;rows=rows-page_size;end if;
 with states as(select distinct on(e.lead_id)e.lead_snapshot,e.search_vector from public.billing_crm_events e where e.business_id=business and e.demo=data_mode and e.lead_snapshot is not null and e.effective_date<=as_of and e.sequence<=ceiling and public.billing_crm_read_lead(e.lead_id) order by e.lead_id,e.effective_date desc,e.sequence desc),groups as(select lead_snapshot->>'pipeline_id' pipeline,lead_snapshot->>'stage_id' stage,lead_snapshot->>'owner_id' owner,lead_snapshot->>'source' source,lead_snapshot->>'currency' currency,lead_snapshot->>'stageKind' kind,count(*) count,sum((lead_snapshot->>'amount')::numeric)::numeric(30,2) amount from states where lead_snapshot->'canonical_id'='null'::jsonb and lead_snapshot->'archived'='false'::jsonb and (pipeline_id is null or lead_snapshot->>'pipeline_id'=billing_crm_read.pipeline_id::text) and (owner_id is null or lead_snapshot->>'owner_id'=billing_crm_read.owner_id::text) and (btrim(search)='' or search_vector@@websearch_to_tsquery('simple',search)) group by 1,2,3,4,5,6)
 select coalesce(jsonb_agg(jsonb_build_object('pipelineId',pipeline,'stageId',stage,'ownerId',owner,'source',source,'currency',currency,'kind',kind,'count',count,'amount',amount::text) order by pipeline,stage,owner,source,currency),'[]'::jsonb) into grouped from groups;
 with states as(select distinct on(e.lead_id)e.lead_id,e.lead_snapshot,e.search_vector from public.billing_crm_events e where e.business_id=business and e.demo=data_mode and e.lead_snapshot is not null and e.effective_date<=as_of and e.sequence<=ceiling and public.billing_crm_read_lead(e.lead_id) order by e.lead_id,e.effective_date desc,e.sequence desc),visible as(select * from states s where (pipeline_id is null or s.lead_snapshot->>'pipeline_id'=billing_crm_read.pipeline_id::text) and(owner_id is null or s.lead_snapshot->>'owner_id'=billing_crm_read.owner_id::text) and(btrim(search)='' or s.search_vector@@websearch_to_tsquery('simple',search))),metrics as(select s.lead_snapshot->>'pipeline_id' pipeline,s.lead_snapshot->>'owner_id' owner,s.lead_snapshot->>'source' source,s.lead_snapshot->>'currency' currency,count(*) sources,count(*) filter(where s.lead_snapshot->>'client_id' is not null) clients,coalesce(sum((select count(*) from public.billing_crm_events e where e.lead_id=s.lead_id and e.business_id=business and e.demo=data_mode and e.sequence<=ceiling and e.effective_date<=as_of and e.kind='quote.create')),0) quotations from visible s group by 1,2,3,4) select coalesce(jsonb_agg(jsonb_build_object('pipelineId',pipeline,'ownerId',owner,'source',source,'currency',currency,'sourceLeads',sources,'linkedClients',clients,'draftQuotations',quotations) order by pipeline,owner,source,currency),'[]'::jsonb) into conversions from metrics;
 with latest as(select distinct on(e.details->'task'->>'id')e.details->'task' task from public.billing_crm_events e where e.business_id=business and e.demo=data_mode and e.sequence<=ceiling and e.effective_date<=as_of and e.details?'task' and public.billing_crm_read_lead(e.lead_id) order by e.details->'task'->>'id',e.effective_date desc,e.sequence desc) select jsonb_build_object('open',count(*) filter(where task->>'status'='open'),'dueThroughDate',count(*) filter(where task->>'status'='open' and ((task->>'due_at')::timestamptz at time zone zone)::date<=as_of),'done',count(*) filter(where task->>'status'='done'),'cancelled',count(*) filter(where task->>'status'='cancelled'),'scope','All currently visible CRM tasks at this date/snapshot; independent of lead search/pipeline filters. Original source tasks remain after merging.') into task_summary from latest;
 select count(*) into legacy_count from public.billing_records r where r.business_id=business and r.demo=data_mode and r.collection='leads' and not r.archived and not exists(select 1 from public.billing_crm_leads l where l.legacy_record_id=r.id);
 if lead_id is not null then
  if not exists(select 1 from public.billing_crm_leads l where l.id=billing_crm_read.lead_id and l.business_id=business and l.demo=data_mode and public.billing_crm_read_lead(l.id)) then raise exception using errcode='P0002',message='Lead unavailable in this CRM scope';end if;
  select e.lead_snapshot into detail from public.billing_crm_events e where e.business_id=business and e.demo=data_mode and e.lead_id=billing_crm_read.lead_id and e.lead_snapshot is not null and e.effective_date<=as_of and e.sequence<=ceiling order by e.effective_date desc,e.sequence desc limit 1;
  if detail is null then raise exception using errcode='P0002',message='Lead has no state at this date/snapshot';end if;
  select l.version into current_version from public.billing_crm_leads l where l.id=billing_crm_read.lead_id;
  detail_can_work=public.billing_crm_work_lead(lead_id) and as_of=today and ceiling=current_ceiling and detail->'archived'='false'::jsonb and detail->'canonical_id'='null'::jsonb;root_id=lead_id;
  loop
   select nullif(e.lead_snapshot->>'canonical_id','')::uuid into parent_id from public.billing_crm_events e where e.business_id=business and e.demo=data_mode and e.lead_id=root_id and e.lead_snapshot is not null and e.effective_date<=as_of and e.sequence<=ceiling order by e.effective_date desc,e.sequence desc limit 1;
   exit when parent_id is null or depth>=32 or not public.billing_crm_read_lead(parent_id);root_id=parent_id;depth=depth+1;
  end loop;
  with recursive states as(select distinct on(e.lead_id)e.lead_id,e.lead_snapshot from public.billing_crm_events e where e.business_id=business and e.demo=data_mode and e.lead_snapshot is not null and e.effective_date<=as_of and e.sequence<=ceiling and public.billing_crm_read_lead(e.lead_id) order by e.lead_id,e.effective_date desc,e.sequence desc),family_tree as(select root_id id union all select s.lead_id from states s join family_tree f on s.lead_snapshot->>'canonical_id'=f.id::text) select array_agg(id) into family from family_tree;
  with states as(select distinct on(e.lead_id)e.lead_id,e.lead_snapshot from public.billing_crm_events e where e.business_id=business and e.demo=data_mode and e.lead_snapshot is not null and e.effective_date<=as_of and e.sequence<=ceiling and e.lead_id=any(family) order by e.lead_id,e.effective_date desc,e.sequence desc) select coalesce(jsonb_agg(lead_snapshot order by (lead_snapshot->>'created_sequence')::bigint),'[]'::jsonb) into aliases from states;
  if after_sequence is not null and not exists(select 1 from public.billing_crm_events e where e.business_id=business and e.demo=data_mode and e.lead_id=any(family) and e.sequence=after_sequence and e.sequence<=ceiling and e.effective_date<=as_of) then raise exception 'CRM timeline cursor does not belong to this dated lead family';end if;
  select count(*) into event_count from public.billing_crm_events e where e.business_id=business and e.demo=data_mode and e.lead_id=any(family) and e.sequence<=ceiling and e.effective_date<=as_of;
  select coalesce(jsonb_agg((to_jsonb(e)-'search_vector')||jsonb_build_object('sequence',e.sequence::text) order by e.sequence),'[]'::jsonb) into timeline from(select * from public.billing_crm_events e where e.business_id=business and e.demo=data_mode and e.lead_id=any(family) and e.sequence<=ceiling and e.effective_date<=as_of and (after_sequence is null or e.sequence>after_sequence) order by e.sequence limit page_size+1)e;
  if jsonb_array_length(timeline)>page_size then next_cursor=jsonb_build_object('after',timeline->(page_size-1)->>'sequence','snapshot',ceiling::text);timeline=timeline-page_size;else next_cursor=null;end if;
  with latest as(select distinct on((e.details->'task'->>'id'))e.details->'task' task from public.billing_crm_events e where e.business_id=business and e.demo=data_mode and e.lead_id=any(family) and e.sequence<=ceiling and e.effective_date<=as_of and e.details?'task' order by (e.details->'task'->>'id'),e.effective_date desc,e.sequence desc) select coalesce(jsonb_agg(task order by task->>'due_at',task->>'id'),'[]'::jsonb) into tasks from latest;
  select coalesce(jsonb_agg(e.details->'activity' order by e.details->'activity'->>'occurred_at',e.sequence),'[]'::jsonb) into activities from public.billing_crm_events e where e.business_id=business and e.demo=data_mode and e.lead_id=any(family) and e.sequence<=ceiling and e.effective_date<=as_of and e.details?'activity';
  select coalesce(jsonb_agg(e.details->'file' order by e.sequence),'[]'::jsonb) into files from public.billing_crm_events e where e.business_id=business and e.demo=data_mode and e.lead_id=any(family) and e.sequence<=ceiling and e.effective_date<=as_of and e.details?'file';
  select coalesce(jsonb_agg(jsonb_build_object('id',q.id,'leadId',q.lead_id,'documentId',q.document_id,'leadVersion',q.lead_version,'snapshot',q.snapshot,'number',e.details->>'documentNumber') order by e.sequence),'[]'::jsonb) into quotes from public.billing_crm_quotes q join public.billing_crm_events e on e.details->>'documentId'=q.document_id::text and e.kind='quote.create' where q.business_id=business and q.demo=data_mode and q.lead_id=any(family) and e.sequence<=ceiling and e.effective_date<=as_of;
 end if;
 return jsonb_build_object('businessId',business,'businessName',business_name,'demo',data_mode,'asOf',as_of,'timeZone',zone,'snapshot',ceiling::text,'canManage',public.billing_crm_manage(business,data_mode),'canWrite',public.billing_can_access(business,true),'canWorkLead',detail_can_work,'userId',auth.uid(),'pipelines',pipelines,'people',people,'leads',rows,'leadCount',lead_count,'legacyUnadopted',legacy_count,'lead',detail,'currentLeadVersion',current_version,'canonicalLeadId',root_id,'aliases',aliases,'timeline',timeline,'timelineCount',event_count,'activities',activities,'tasks',tasks,'files',files,'quotes',quotes,'report',grouped,'conversionReport',conversions,'taskSummary',task_summary,'conversionScope','Counts of retained source leads, current-as-of linked clients and immutable draft-quotation creation events. Multiple quotation drafts are counted separately, not claimed as sales or provider delivery. Includes archived/merged provenance; same search/pipeline/owner filters.','next',next_cursor,'reportScope','Current CRM visibility applied to dated lead snapshots; currencies remain separate. Merged/archived source records are retained and excluded from active opportunity totals. Pipeline/stage labels are their recorded versions.','historyScope','Tasks/activities/files/quotes retain original source lead IDs after explicit merges. Timeline is paged; related typed collections are complete through this snapshot.');
end$$;

create function public.billing_crm_duplicates(business uuid,data_mode boolean,email text,phone text) returns jsonb language plpgsql stable security definer set search_path='' as $$declare matches jsonb;hidden bigint;begin
 if auth.uid() is null or not public.billing_can_access(business) then raise exception using errcode='42501',message='CRM unavailable';end if;
 if data_mode is null or email is null or phone is null or length(email)>254 or length(phone)>80 then raise exception 'Review exact contact identities';end if;
 select coalesce(jsonb_agg(public.billing_crm_lead_json(l.id) order by l.created_sequence),'[]'::jsonb) into matches from public.billing_crm_leads l where l.business_id=business and l.demo=data_mode and l.canonical_id is null and not l.archived and public.billing_crm_read_lead(l.id) and (btrim(billing_crm_duplicates.email)<>'' and lower(l.email)=lower(btrim(billing_crm_duplicates.email)) or regexp_replace(billing_crm_duplicates.phone,'[^0-9]','','g')<>'' and regexp_replace(l.phone,'[^0-9]','','g')=regexp_replace(billing_crm_duplicates.phone,'[^0-9]','','g'));
 select count(*) into hidden from public.billing_crm_leads l where l.business_id=business and l.demo=data_mode and l.canonical_id is null and not l.archived and not public.billing_crm_read_lead(l.id) and (btrim(billing_crm_duplicates.email)<>'' and lower(l.email)=lower(btrim(billing_crm_duplicates.email)) or regexp_replace(billing_crm_duplicates.phone,'[^0-9]','','g')<>'' and regexp_replace(l.phone,'[^0-9]','','g')=regexp_replace(billing_crm_duplicates.phone,'[^0-9]','','g'));
 return jsonb_build_object('businessId',business,'demo',data_mode,'matches',matches,'managerReviewRequired',hidden>0,'policy','Exact normalized email/phone candidates only. Names never auto-merge records; ownership and survivor require explicit review.');
end$$;
revoke all on function public.billing_crm_writer(uuid,uuid),public.billing_crm_manage(uuid,boolean),public.billing_crm_canonical(uuid),public.billing_crm_read_lead(uuid),public.billing_crm_work_lead(uuid),public.billing_crm_next(uuid,boolean),public.billing_crm_emit(uuid,boolean,uuid,bigint,text,uuid,date,jsonb,jsonb),public.billing_crm_lead_json(uuid),public.billing_crm_immutable(),public.billing_crm_version_guard(),public.billing_crm_command(uuid,boolean,uuid,text,jsonb),public.billing_crm_legacy_guard(),public.billing_crm_quote_guard(),public.billing_crm_storage_allowed(text,boolean),public.billing_crm_read(uuid,boolean,date,uuid,bigint,integer,bigint,text,uuid,uuid,boolean),public.billing_crm_duplicates(uuid,boolean,text,text) from public,anon,authenticated;
grant execute on function public.billing_crm_command(uuid,boolean,uuid,text,jsonb),public.billing_crm_read(uuid,boolean,date,uuid,bigint,integer,bigint,text,uuid,uuid,boolean),public.billing_crm_duplicates(uuid,boolean,text,text),public.billing_crm_manage(uuid,boolean),public.billing_crm_read_lead(uuid),public.billing_crm_work_lead(uuid),public.billing_crm_storage_allowed(text,boolean) to authenticated;
notify pgrst,'reload schema';
